-- ============================================================
--  LIBRERÍA LA INMACULADA - DATOS INICIALES (v7)
-- ------------------------------------------------------------
--  Ejecutar DESPUÉS de LibreriaLaInmaculada_v7.sql, con la base vacía.
--  Si ya hay datos, el script se detiene sin tocar nada.
--
--  Contenido (año escolar 2026 en Managua, del 5 de enero al 10 de noviembre):
--    * 2 usuarios: ADMIN (dueños) y jporras (Jorge Porras, vendedor)
--    * 8 categorías, 8 proveedores (sucursales de Gonper, Librería Jardín y Universal;
--      contactos y algunos datos inventados para la simulación)
--    * 50 artículos que se venden POR UNIDAD (un lápiz, un borrador, una hoja...)
--    * 25 compras (108 líneas) con IVA 15 %
--    * 2109 ventas (3731 líneas), 2 anuladas
--    * 12 pérdidas
--  Montos en córdobas (C$). Precios aproximados para el proyecto.
--
--  Las compras se registran en unidades: una caja de 48 lápices entra
--  como 48 unidades de "Lápiz de grafito No. 2", una resma como 500 hojas.
--
--  El stock NO se escribe a mano: al final se calcula como
--  compras activas - ventas activas - pérdidas, y los totales de cada
--  compra y venta salen de su detalle.
--
--  Usuarios (cambiar las contraseñas en producción):
--    ADMIN   / Admin2026!   (Administrador)
--    jporras / Jorge2026!   (Vendedor)
--  Hash: PBKDF2-SHA256, 100 000 iteraciones, salt 16 B, hash 32 B
-- ============================================================

USE LibreriaLaInmaculada;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF EXISTS (SELECT 1 FROM dbo.Usuarios) OR EXISTS (SELECT 1 FROM dbo.CAT_Articulos)
BEGIN
    RAISERROR('La base ya tiene datos. Ejecute primero LibreriaLaInmaculada_v7.sql para dejarla vacía.', 16, 1);
    RETURN;
END;

-- XACT_ABORT ON: si cualquier instrucción falla, se deshace TODO y no queda la base a medias
