-- ============================================================
-- Totales y stock calculados desde los movimientos
-- ============================================================
UPDATE CO
SET    CO.SubTotal = D.SubTotal, CO.IVA = D.IVA, CO.Fecha_Actualizacion = CO.Fecha_Registro
FROM   dbo.Compra CO
JOIN  (SELECT idCompra, SUM(SubTotal) AS SubTotal, SUM(IVA) AS IVA
       FROM dbo.Compra_Detalle GROUP BY idCompra) D ON D.idCompra = CO.idCompra;

UPDATE V
SET    V.Total = D.Total
FROM   dbo.Venta V
JOIN  (SELECT idVenta, SUM(Total) AS Total FROM dbo.Venta_Detalle GROUP BY idVenta) D ON D.idVenta = V.idVenta;

UPDATE A
SET    A.Cantidad = ISNULL(C.Q, 0) - ISNULL(V.Q, 0) - ISNULL(P.Q, 0),
       A.Precio_Compra       = ISNULL(U.Precio_Compra_Unitario, A.Precio_Compra),
       A.Fecha_Actualizacion = ISNULL(U.Fecha_Compra, A.Fecha_Actualizacion)
FROM   dbo.CAT_Articulos A
LEFT JOIN (SELECT CD.idArticulo, SUM(CD.Cantidad) Q FROM dbo.Compra_Detalle CD
           JOIN dbo.Compra CO ON CO.idCompra = CD.idCompra WHERE CO.Estado = 'Activa'
           GROUP BY CD.idArticulo) C ON C.idArticulo = A.idArticulo
LEFT JOIN (SELECT VD.idArticulo, SUM(VD.Cantidad) Q FROM dbo.Venta_Detalle VD
           JOIN dbo.Venta V ON V.idVenta = VD.idVenta WHERE V.Estado = 'Activa'
           GROUP BY VD.idArticulo) V ON V.idArticulo = A.idArticulo
LEFT JOIN (SELECT idArticulo, SUM(Cantidad) Q FROM dbo.Perdidas_Devoluciones
           GROUP BY idArticulo) P ON P.idArticulo = A.idArticulo
OUTER APPLY (SELECT TOP (1) CD.Precio_Compra_Unitario, CO.Fecha_Compra
             FROM dbo.Compra_Detalle CD JOIN dbo.Compra CO ON CO.idCompra = CD.idCompra
             WHERE CD.idArticulo = A.idArticulo AND CO.Estado = 'Activa'
             ORDER BY CO.Fecha_Compra DESC, CO.idCompra DESC) U;

COMMIT TRANSACTION;
PRINT 'Datos iniciales v7 cargados correctamente.';
GO

-- ============================================================
-- VERIFICACIÓN
-- ============================================================
SELECT 'Usuarios' AS Tabla, COUNT(*) AS Filas FROM dbo.Usuarios
UNION ALL SELECT 'Proveedores', COUNT(*) FROM dbo.CAT_Proveedor
UNION ALL SELECT 'Artículos', COUNT(*) FROM dbo.CAT_Articulos
UNION ALL SELECT 'Compras', COUNT(*) FROM dbo.Compra
UNION ALL SELECT 'Líneas de compra', COUNT(*) FROM dbo.Compra_Detalle
UNION ALL SELECT 'Ventas', COUNT(*) FROM dbo.Venta
UNION ALL SELECT 'Líneas de venta', COUNT(*) FROM dbo.Venta_Detalle
UNION ALL SELECT 'Pérdidas', COUNT(*) FROM dbo.Perdidas_Devoluciones;

-- Ventas y ganancia por mes (se nota el pico de inicio de clases)
SELECT YEAR(Fecha_Venta) AS Anio, MONTH(Fecha_Venta) AS Mes, COUNT(DISTINCT idVenta) AS Ventas,
       SUM(Total) AS Vendido_CS, SUM(Ganancia) AS Ganancia_CS
FROM dbo.V_VentaDetalle WHERE Estado = 'Activa'
GROUP BY YEAR(Fecha_Venta), MONTH(Fecha_Venta) ORDER BY Anio, Mes;

-- Artículos que hay que reabastecer
SELECT Descripcion, Stock_Disponible, Stock_Minimo FROM dbo.V_Articulos WHERE Bajo_Stock = 1;

-- Integridad: debe devolver 0 filas
SELECT A.idArticulo, A.Descripcion, A.Cantidad,
       ISNULL(C.Q,0) - ISNULL(V.Q,0) - ISNULL(P.Q,0) AS Stock_Calculado
FROM dbo.CAT_Articulos A
OUTER APPLY (SELECT SUM(CD.Cantidad) Q FROM dbo.Compra_Detalle CD JOIN dbo.Compra CO ON CO.idCompra = CD.idCompra
             WHERE CD.idArticulo = A.idArticulo AND CO.Estado = 'Activa') C
OUTER APPLY (SELECT SUM(VD.Cantidad) Q FROM dbo.Venta_Detalle VD JOIN dbo.Venta V ON V.idVenta = VD.idVenta
             WHERE VD.idArticulo = A.idArticulo AND V.Estado = 'Activa') V
OUTER APPLY (SELECT SUM(PD.Cantidad) Q FROM dbo.Perdidas_Devoluciones PD WHERE PD.idArticulo = A.idArticulo) P
WHERE A.Cantidad <> ISNULL(C.Q,0) - ISNULL(V.Q,0) - ISNULL(P.Q,0);
GO
